@pytest.mark.parametrize("site", ["sampling", "select"]) @pytest.mark.parametrize("error_type", [OSError, ValueError]) def test_readiness_failure_preserves_safety_retirement(monkeypatch, site, error_type): """Advisory failures must not bypass the real retirement callback's authority.""" import errno import os import signal
import worker_capture
now, sleeps = clock(monkeypatch) pid = 2**30 signals = [] reaps = [] failures = [] monkeypatch.setattr(worker_capture, "_owners", {}) monkeypatch.setattr(os, "fork", lambda: pid) monkeypatch.setattr(os, "kill", lambda child, sig: signals.append((child, sig)))
def waitpid(child, flags): assert child == pid and flags == os.WNOHANG reaps.append(now[0]) return (pid, 0) if (pid, signal.SIGKILL) in signals else (0, 0)
def read(_fd, _size): raise BlockingIOError
def fail(*_args): failures.append(now[0]) assert len(failures) < 100, "readiness error spun without bounded timer progress" raise error_type(errno.EBADF, "injected advisory failure")
def drive(subject): if not subject.safety: # Expire the query without mocking the safety implementation. now[0] = 10.95 assert subject.advance() is None return assert subject.readiness is not None if site == "select": monkeypatch.setattr(turns.select, "select", fail) interests = subject.readiness else: interests = fail turns.run_turns(turns.Turn(subject.advance, safety=True, readiness=interests))
monkeypatch.setattr(os, "waitpid", waitpid) monkeypatch.setattr(os, "read", read) monkeypatch.setattr(worker_capture, "run_turns", drive) receipt = worker_capture.capture_helper(("/usr/bin/true",), 11.0) assert failures and sleeps assert signals == [(pid, signal.SIGTERM), (pid, signal.SIGKILL)] > assert 10.9625 <= reaps[-1] <= 11.0 E assert 10.9625 <= 10.962499999999999
